<?php declare(strict_types=1);require_once __DIR__.'/auth_check.php';require_once __DIR__.'/bootstrap.php';$db=app_database();$_SESSION['ledger_csrf']??=bin2hex(random_bytes(24));$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-t');$sum=static function(string $sql,array $p=[])use($db):float{$s=$db->prepare($sql);$s->execute($p);return(float)$s->fetchColumn();};$o=$db->query('SELECT opening_balance,opening_date FROM treasury_settings WHERE id=1')->fetch();$received=(float)$o['opening_balance']+$sum('SELECT COALESCE(SUM(montant),0) FROM encaissements')+$sum("SELECT COALESCE(SUM(CASE WHEN movement_type IN('manual_entry','return_to_entries') THEN amount ELSE 0 END),0) FROM treasury_ledger")-$sum("SELECT COALESCE(SUM(amount),0) FROM treasury_ledger WHERE movement_type='transfer_to_available'");$transfers=$sum("SELECT COALESCE(SUM(CASE WHEN movement_type='transfer_to_available' THEN amount WHEN movement_type='return_to_entries' THEN -amount ELSE 0 END),0) FROM treasury_ledger");$available=$transfers-$sum("SELECT COALESCE(SUM(amount),0) FROM treasury_ledger WHERE movement_type='manual_out'")-$sum('SELECT COALESCE(SUM(montant),0) FROM decaissements');$reserved=$sum("SELECT COALESCE(SUM(amount),0) FROM feb_funding_plans WHERE source_type='real' AND status IN('planned','closed')");$forecast=$sum("SELECT COALESCE(SUM(GREATEST(f.montant_ttc-COALESCE(p.paid,0),0)),0) FROM factures_clients f LEFT JOIN(SELECT facture_id,SUM(montant)paid FROM encaissements GROUP BY facture_id)p ON p.facture_id=f.id WHERE f.collection_tracking_status<>'cancelled'");$validation=$sum("SELECT COALESCE(SUM(amount),0) FROM disbursement_authorizations WHERE status='purchase_validation'");$due=$sum("SELECT COALESCE(SUM(amount),0) FROM feb_funding_plans WHERE status='planned' AND scheduled_date<=:d",['d'=>$to]);$future=$sum("SELECT COALESCE(SUM(amount),0) FROM feb_funding_plans WHERE status='planned' AND scheduled_date>:d",['d'=>$to]);$projection=max(0,$sum('SELECT COALESCE(SUM(montant),0) FROM debourse_lignes')-$sum('SELECT COALESCE(SUM(montant),0) FROM decaissements'));$invoices=$db->query("SELECT f.*,c.nom_client,GREATEST(f.montant_ttc-COALESCE(p.paid,0),0) remaining,DATEDIFF(CURRENT_DATE,COALESCE(f.expected_collection_date,f.date_echeance)) overdue FROM factures_clients f JOIN bons_commande bc ON bc.id=f.bon_commande_id LEFT JOIN client c ON c.id_client=bc.client_id LEFT JOIN(SELECT facture_id,SUM(montant)paid FROM encaissements GROUP BY facture_id)p ON p.facture_id=f.id WHERE f.collection_tracking_status<>'cancelled' AND GREATEST(f.montant_ttc-COALESCE(p.paid,0),0)>0")->fetchAll();$flash=$_SESSION['ledger_flash']??null;unset($_SESSION['ledger_flash']);function ch($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function cm($v){return number_format((float)$v,0,',',' ').' FCFA';}$cards=[['Prévisionnel','Entrées prévisionnelles',$forecast,'Échéances et factures en retard'],['Réservé sans débit','Réservations FEB',$reserved,'Aucun double débit'],['Réel','Solde non réservé',$received-$reserved,'Entrées après réservations'],['Réel','Entrées réelles',$received,'Fonds reçus non transférés'],['Disponible','Disponible mobilisable',$available,'Après sorties réellement exécutées'],['Prévisionnel','En validation achat',$validation,'Fiches prêtes pour validation achat'],['Prévisionnel','FEB à traiter',$due,'Prévues avant la fin de période'],['Prévisionnel','FEB à venir',$future,'Prévues après la période'],['Prévisionnel','Projection déboursé',$projection,'Reste global à payer']];?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trésorerie · FIDEST</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="css/style.css"><link rel="stylesheet" href="css/modules.css"><style>.cash{max-width:1450px}.hero{padding:28px;color:#fff;background:linear-gradient(125deg,#182044,#41477b);border-radius:22px}.hero h1{color:#fff!important}.toolbar,.block{padding:20px;margin-top:17px;background:#fff;border:1px solid var(--brand-border);border-radius:18px}.actions,.cards{display:flex;gap:8px;flex-wrap:wrap}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.cardx{padding:20px;border:1px solid #e5e5ec;border-radius:16px}.cardx small,.cardx strong{display:block}.cardx strong{margin:8px 0;color:var(--brand-primary);font-size:1.35rem}.kind{color:#777;font-size:.62rem;font-weight:900;text-transform:uppercase}.move{display:none}.move.open{display:block}.invoice{padding:15px;margin-top:10px;border:1px solid #e5e5ec;border-radius:13px}@media(max-width:900px){.cards{grid-template-columns:1fr 1fr}}@media(max-width:550px){.cards{grid-template-columns:1fr}}</style></head><body class="module-page"><?php include __DIR__.'/partials/navbar.php';?><main class="container cash"><header class="hero"><small>SITUATION FINANCIÈRE EN TEMPS RÉEL</small><h1>Trésorerie</h1><p>Les fonds reçus restent dans les entrées réelles jusqu’à leur transfert explicite vers le disponible. Un même montant ne figure jamais simultanément dans les deux soldes.</p><div class="actions"><?php foreach(['initialize'=>'Initialiser le solde','transfer'=>'Alimenter le disponible','entry'=>'Nouvelle entrée','out'=>'Nouvelle sortie','return'=>'Retourner le disponible aux entrées']as$a=>$l):?><button class="btn <?=$a==='initialize'?'btn-warning':'btn-light'?>" data-form="<?=$a?>"><?=$l?></button><?php endforeach;?></div></header><?php if($flash):?><div class="alert alert-<?=ch($flash['type'])?> mt-3"><?=ch($flash['message'])?></div><?php endif;?><section class="toolbar"><form class="row g-2"><div class="col"><input class="form-control" type="date" name="from" value="<?=ch($from)?>"></div><div class="col"><input class="form-control" type="date" name="to" value="<?=ch($to)?>"></div><div class="col"><button class="btn btn-primary">Afficher</button></div></form><?php foreach(['initialize','transfer','entry','out','return']as$a):?><form id="<?=$a?>" class="move mt-3" method="post" action="request/treasury_ledger_action.php"><input type="hidden" name="csrf" value="<?=ch($_SESSION['ledger_csrf'])?>"><input type="hidden" name="action" value="<?=$a?>"><div class="row g-2"><div class="col"><input required class="form-control" name="amount" type="number" step=".01" placeholder="Montant"></div><div class="col"><input required class="form-control" name="date" type="date" value="<?=date('Y-m-d')?>"></div><div class="col"><input class="form-control" name="reference" placeholder="Référence / note"></div><div class="col"><button class="btn btn-primary">Enregistrer</button></div></div></form><?php endforeach;?></section><section class="block"><h2>Entrées, soldes et sorties</h2><div class="cards"><?php foreach($cards as[$k,$l,$v,$n]):?><article class="cardx"><span class="kind"><?=ch($k)?></span><small><?=ch($l)?></small><strong><?=cm($v)?></strong><span><?=ch($n)?></span><a class="d-block mt-2" href="<?=$l==='En validation achat'?'planification_decaissements.php':'#'?>">Voir le récapitulatif</a></article><?php endforeach;?></div></section><section class="block"><h2>Encaissements à confirmer</h2><?php foreach($invoices as$i):?><article class="invoice"><strong><?=ch($i['numero_facture'])?> · <?=cm($i['remaining'])?></strong><?php if($i['overdue']>0):?><span class="badge text-bg-danger float-end">Date dépassée · <?=(int)$i['overdue']?> jours</span><?php endif;?><small class="d-block">Encaissement facture · <?=ch($i['nom_client'])?> · réception prévue le <?=ch($i['expected_collection_date']?:$i['date_echeance'])?></small><form class="row g-2 mt-2" method="post" action="request/treasury_ledger_action.php"><input type="hidden" name="csrf" value="<?=ch($_SESSION['ledger_csrf'])?>"><input type="hidden" name="invoice_id" value="<?=(int)$i['id']?>"><div class="col"><input class="form-control" name="amount" value="<?=ch($i['remaining'])?>"></div><div class="col"><input class="form-control" type="date" name="date" value="<?=date('Y-m-d')?>"></div><div class="col"><input class="form-control" name="note" placeholder="Motif pour report/annulation"></div><div class="col actions"><button class="btn btn-success" name="action" value="confirm_invoice">Fonds perçus</button><button class="btn btn-warning" name="action" value="postpone_invoice">Reporter</button><button class="btn btn-danger" name="action" value="cancel_invoice">Annuler</button></div></form></article><?php endforeach;?></section></main><script>document.querySelectorAll('[data-form]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.form).classList.toggle('open'))</script></body></html>
